#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int*)b - *(int*)a);
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int prices[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &prices[i]);
    }

    // sort prices descending
    qsort(prices, n, sizeof(int), cmp);

    // prefix sums for fast sum of top k manju
    long long prefix[n+1];
    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        prefix[i+1] = prefix[i] + prices[i];
    }

    long long max_profit = 0;
    for (int i = 0; i < m; i++) {
        int capacity, cost;
        scanf("%d %d", &capacity, &cost);
        if (capacity > n) capacity = n;
        long long revenue = prefix[capacity];
        long long profit = revenue - cost;
        if (profit > max_profit) {
            max_profit = profit;
        }
    }

    printf("%lld\n", max_profit);
    return 0;
}

