typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    ll *manju = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &manju[i]);

    int *cap = (int *)malloc(sizeof(int) * M);
    ll *cost = (ll *)malloc(sizeof(ll) * M);

    int maxCap = 0;
    for (int i = 0; i < M; i++) {
        scanf("%d %lld", &cap[i], &cost[i]);
        if (cap[i] > maxCap) maxCap = cap[i];
    }

    qsort(manju, N, sizeof(ll), cmp_ll);

    ll *prefix = (ll *)malloc(sizeof(ll) * (N + 1));
    prefix[0] = 0;
    for (int i = 0; i < N; i++) prefix[i + 1] = prefix[i] + manju[i];

    const ll NEG = -(1LL << 60);
    ll *best = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 0; i <= N; i++) best[i] = NEG;

    for (int i = 0; i < M; i++) {
        if (cap[i] <= N) {
            if (cost[i] > best[cap[i]]) best[cap[i]] = cost[i];
        }
    }

    for (int i = N - 1; i >= 1; i--) {
        if (best[i + 1] > best[i]) best[i] = best[i + 1];
    }

    ll ans = 0;
    for (int k = 1; k <= N; k++) {
        if (best[k] == NEG) continue;
        ll sumLargestK = prefix[N] - prefix[N - k];
        ll profit = sumLargestK - best[k];
        if (profit > ans) ans = profit;
    }

    printf("%lld\n", ans);

    free(manju);
    free(cap);
    free(cost);
    free(prefix);
    free(best);
    return 0;
}

