int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> manjuPrice(n);
    for (int i = 0; i < n; i++) {
        cin >> manjuPrice[i];
    }

    vector<pair<int, int>> boxes(m);
    for (int i = 0; i < m; i++) {
        cin >> boxes[i].first >> boxes[i].second;
    }

    // Sort manju in descending price
    sort(manjuPrice.rbegin(), manjuPrice.rend());

    // prefix sum for quick sum of top k manju
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + manjuPrice[i];
    }

    const long long NEG_INF = -1e18;
    // bestBoxProfit[k] = max profit by selling exactly k manju in one box
    vector<long long> bestBoxProfit(n + 1, NEG_INF);
    bestBoxProfit[0] = 0;
    for (int k = 1; k <= n; k++) {
        for (auto& box : boxes) {
            int cap = box.first;
            int price = box.second;
            if (k <= cap) {
                bestBoxProfit[k] = max(bestBoxProfit[k], prefix[k] - price);
            }
        }
    }

    // unbounded knapsack: dp[i] = max profit selling exactly i manju
    vector<long long> dp(n + 1, NEG_INF);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int k = 1; k <= i; k++) {
            if (bestBoxProfit[k] != NEG_INF && dp[i - k] != NEG_INF) {
                dp[i] = max(dp[i], dp[i - k] + bestBoxProfit[k]);
            }
        }
    }

    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        ans = max(ans, dp[i]);
    }
    cout << ans << "\n";

    return 0;
}

