        long long best = 0;
        int bestCap = -1;
        for (auto& [cap, cost] : boxes) {
            if (pos + cap <= N) {
                long long profit = prefix[pos+cap] - prefix[pos] - cost;
                if (profit > best) {
                    best = profit;
                    bestCap = cap;
