int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<long long> manju(N);
    for (int i = 0; i < N; ++i) cin >> manju[i];

    vector<pair<int, long long>> boxes(M);
    for (int i = 0; i < M; ++i) {
        int c;
        long long p;
        cin >> c >> p;
        boxes[i] = {c, p};
    }

    sort(manju.begin(), manju.end(), greater<long long>());

    vector<long long> prefix(N + 1, 0);
    for (int i = 0; i < N; ++i) prefix[i + 1] = prefix[i] + manju[i];

    const long long INF = (1LL << 60);
    vector<long long> minCost(N + 1, INF);

    for (auto &[cap, price] : boxes) {
        if (cap <= N) minCost[cap] = min(minCost[cap], price);
    }

    for (int i = N - 1; i >= 1; --i) {
        minCost[i] = min(minCost[i], minCost[i + 1]);
    }

    long long ans = 0;
    for (int k = 1; k <= N; ++k) {
        if (minCost[k] == INF) continue;
        ans = max(ans, prefix[k] - minCost[k]);
    }

    cout << ans << '\n';
    return 0;
}

