        for (int i = 0; i < N / 2; i++) {
            int temp = manjuPrices[i];
            manjuPrices[i] = manjuPrices[N - 1 - i];
            manjuPrices[N - 1 - i] = temp;
        }

        // prefix sum of manju prices
        long[] prefixSum = new long[N + 1];
        for (int i = 0; i < N; i++) {
            prefixSum[i + 1] = prefixSum[i] + manjuPrices[i];
        }

