        // For each box type, consider using it to sell some number of manju
        for (int i = 0; i < M; i++) {
            int cap = boxCapacities[i];
            int cost = boxPrices[i];
            int sellCount = Math.min(cap, N);
            long revenue = prefixSum[sellCount];
            long profit = revenue - cost;
            if (profit > maxProfit) {
                maxProfit = profit;
            }
        }

        System.out.println(maxProfit);
    }
