import java.util.*;

/*
The statement provided is incomplete, but the intended task is the classic:
- There are N manju with given prices.
- There are M box types; each box type has capacity C and cost P.
- A sold set consists of some manju packed into one box, with number of manju in the set
  not exceeding the box capacity.
- Sale price of a set = sum of prices of manju in that set.
- Profit = total sale price of sold manju - total cost of boxes used.
- We may choose any partition of some/all manju into boxed sets to maximize profit.

Optimal interpretation:
For any set size k, if we use one box to sell k manju, we should use the cheapest box
with capacity >= k. Let minBoxCost[k] be that minimum cost.
Then if manju prices are sorted descending, the best set of size k has value equal to
the sum of the k most expensive remaining manju. This leads to DP on prefixes.

DP:
Sort manju prices descending: a[1..N]
prefix[i] = sum of first i prices
cost[k] = minimum box cost with capacity >= k, else INF

dp[i] = maximum profit using first i manju in sorted order
dp[0] = 0
dp[i] = max(
    dp[i-1],   // skip i-th manju
    max over k=1..i with cost[k] finite:
        dp[i-k] + (prefix[i] - prefix[i-k]) - cost[k]
)

This is O(N^2 + M + maxCap). Without constraints in the prompt, this is the safest
general solution.

Input assumed:
N M
A1 A2 ... AN
then M lines:
Cj Pj

Output:
maximum profit
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int M = fs.nextInt();

        long[] a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        int[] cap = new int[M];
        long[] price = new long[M];
        int maxCap = 0;
        for (int i = 0; i < M; i++) {
            cap[i] = fs.nextInt();
            price[i] = fs.nextLong();
            maxCap = Math.max(maxCap, cap[i]);
        }

        Arrays.sort(a);
        for (int i = 0, j = N - 1; i < j; i++, j--) {
            long tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }

        long[] prefix = new long[N + 1];
        for (int i = 1; i <= N; i++) prefix[i] = prefix[i - 1] + a[i - 1];

        final long INF = Long.MAX_VALUE / 4;
        int limit = Math.max(N, maxCap);
        long[] best = new long[limit + 2];
        Arrays.fill(best, INF);

        for (int i = 0; i < M; i++) {
            if (price[i] < best[cap[i]]) best[cap[i]] = price[i];
        }

        for (int i = limit - 1; i >= 1; i--) {
            best[i] = Math.min(best[i], best[i + 1]);
        }

        long[] cost = new long[N + 1];
        Arrays.fill(cost, INF);
        for (int k = 1; k <= N; k++) {
            if (k <= limit) cost[k] = best[k];
        }

        long[] dp = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            dp[i] = dp[i - 1]; // skip this manju
            for (int k = 1; k <= i; k++) {
                if (cost[k] >= INF / 2) continue;
                long gain = (prefix[i] - prefix[i - k]) - cost[k];
                dp[i] = Math.max(dp[i], dp[i - k] + gain);
            }
        }

        System.out.println(dp[N]);
    }
}

import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    manju_prices = [int(next(it)) for _ in range(n)]

    boxes = []
    max_cap = 0
    for _ in range(m):
        c = int(next(it))
        p = int(next(it))
        boxes.append((c, p))
        if c > max_cap:
            max_cap = c

    # Unbounded knapsack to get max total manju price for each capacity
    dp = [0] * (max_cap + 1)
    for cap in range(1, max_cap + 1):
        best = 0
        for price in manju_prices:
            if cap >= price:
                best = max(best, dp[cap - price] + price)
        dp[cap] = best

    max_profit = 0
    for cap, box_price in boxes:
        if cap <= max_cap:
            profit = dp[cap] - box_price
            if profit > max_profit:
                max_profit = profit

    print(max_profit)

